import json
from pathlib import Path
base=Path('data')
for name in ['company.json','vendors.json','customers.json','ar_customers.json','ar_invoices.json','invoices.json','purchase_orders.json']:
 p=base/name
 print('====',name,'exists',p.exists())
 if p.exists():
  d=json.loads(p.read_text())
  if isinstance(d,list):
   print('list len',len(d))
   if d: print(json.dumps(d[0],indent=2)[:800])
  elif isinstance(d,dict):
   print('keys',list(d.keys())[:30])
   print(json.dumps(d,indent=2)[:1500])
print('==== close')
for p in Path('data/close').rglob('*'):
 if p.is_file():
  print(p)
  try:
   t=p.read_text()[:500]
   print(t)
  except: pass
print('==== canonical')
for p in list(Path('data/canonical').rglob('*'))[:40]:
 print(p)
